SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;
SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;
SET NAMES utf8mb4;

-- Step 1: Remove UNIQUE constraint on customers(email) to allow family/broker shared emails
SET @drop_sql = IF(
    (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'customers' AND index_name = 'UK_rfbvkrffamfql7cjmen8v976v') > 0,
    'ALTER TABLE customers DROP INDEX `UK_rfbvkrffamfql7cjmen8v976v`',
    'SELECT 1'
);
PREPARE stmt1 FROM @drop_sql;
EXECUTE stmt1;
DEALLOCATE PREPARE stmt1;

SET @add_sql = IF(
    (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'customers' AND index_name = 'idx_customer_email') = 0,
    'ALTER TABLE customers ADD INDEX `idx_customer_email` (`email`)',
    'SELECT 1'
);
PREPARE stmt2 FROM @add_sql;
EXECUTE stmt2;
DEALLOCATE PREPARE stmt2;

START TRANSACTION;

